@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogFrontPage>
@{
    Layout = null;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>@Model.Value(x => x.Title)</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true">
</head>
<body class="bg-gray-50 text-gray-900">
    <div class="container mx-auto px-4 py-12">
        <header class="mb-12">
            <h1 class="text-4xl font-bold text-blue-600 mb-4">@Model.Value(x => x.Title)</h1>
            @if (!string.IsNullOrEmpty(Model.Value(x => x.Intro)))
            {
                <p class="text-xl text-gray-700 mb-8">@Model.Value(x => x.Intro)</p>
            }
        </header>

        <div class="mb-16">
            <h2 class="text-2xl font-semibold text-gray-800 mb-8">Recent Posts</h2>
            <div class="grid md:grid-cols-2 gap-8">
                @foreach (var post in Model.Children<BlogPost>()) {
                    <article class="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow">
                        <div class="p-6">
                            @if (post.Value(x => x.ListingImage) != null)
                            {
                                var imageUrl = Umbraco.GetCropUrl(post.Value(x => x.ListingImage), "listingImage");
                                <img src="@imageUrl" alt="@post.Name" class="w-full h-48 object-cover rounded-t-lg">
                            }
                        </div>
                        <div class="p-6">
                            <h3 class="text-xl font-bold text-gray-900 mb-2">
                                <a href="@post.Url()" class="hover:text-blue-600 transition-colors">@post.Value(x => x.Title)</a>
                            </h3>
                            <p class="text-gray-600 text-sm mb-2">
                                @post.Value(x => x.PublishDate).ToString("MMMM dd, yyyy")
                            </p>
                            <p class="text-gray-700 mb-4">@post.Value(x => x.Excerpt)</p>
                            <a href="@post.Url()" class="inline-block bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 transition-colors">Read More</a>
                        </div>
                    </article>
                }
            </div>
        </div>

        <section class="bg-white rounded-lg shadow-md p-8">
            <h2 class="text-2xl font-semibold text-gray-800 mb-6">About This Blog</h2>
            @await Html.GetBlockGridHtmlAsync(Model, "body")
        </section>
    </div>
</body>
</html>

