@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<RichTextBlock>>

@{
    var htmlContent = Model.Content.Text?.ToHtmlString();
}

@if (!string.IsNullOrEmpty(htmlContent))
{
    <div class="my-8">
        @Html.Raw(htmlContent)
    </div>
}

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>

@{
    var image = Model.Content.Image;
    var caption = Model.Content.Caption;
}

@if (image != null)
{
    var imageUrl = Umbraco.GetCropUrl(image, "image");
    <div class="my-8 text-center">
        <img src="@imageUrl" alt="@caption" class="max-w-full h-auto mx-auto rounded-lg shadow-md">
        @if (!string.IsNullOrEmpty(caption))
        {
            <p class="text-sm text-gray-600 mt-3 italic">@caption</p>
        }
    </div>
}

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlockGridItem<QuoteBlock>>

@{
    var quote = Model.Content.Quote;
    var attribution = Model.Content.Attribution;
}

@if (!string.IsNullOrEmpty(quote))
{
    <div class="my-8 bg-gray-100 rounded-lg p-8 border-l-4 border-blue-500">
        <blockquote class="text-xl italic text-gray-800">
            @quote
        </blockquote>
        @if (!string.IsNullOrEmpty(attribution))
        {
            <cite class="block mt-4 text-right text-gray-600">— @attribution</cite>
        }
    </div>
}

